$ErrorActionPreference='Stop'
if($PSVersionTable.PSEdition-eq'Core'){$ps5=Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe';&$ps5 -NoProfile -ExecutionPolicy Bypass -STA -File $PSCommandPath;if($LASTEXITCODE-ne0){throw ('Windows PowerShell test failed: '+$LASTEXITCODE)};return}
$root=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path;&(Join-Path $root 'app-studio.ps1') -CompileOnly
$temp=Join-Path ([IO.Path]::GetTempPath()) ('pui-diagnostics-'+[Guid]::NewGuid().ToString('N'));New-Item -ItemType Directory $temp|Out-Null
try{$r=New-Object AppStudio.SessionRecorder((Join-Path $temp 'shots'));$codes=@('UIA-TIMEOUT','WIN32-HUNG','CAP-BLACK');foreach($code in $codes){$r.AddFailure('injected',$code,('Injected '+$code+' detail.'),'el-0001')};$json=[AppStudio.JsonWriter]::Write($r.ToJson());$screen=[AppStudio.DiagnosticProjection]::Screen($r.Data);$pack=[AppStudio.PackWriter]::Write($r.Data,(Join-Path $temp 'pack'));$html=Get-Content (Join-Path $pack.Folder 'report.html') -Raw;$log=Get-Content (Join-Path $pack.Folder 'diagnostics.log') -Raw;foreach($code in $codes){foreach($projection in @($json,$screen,$html,$log)){if(-not$projection.Contains($code)){throw ($code+' missing from a projection')}}};if((Get-Content (Join-Path $pack.Folder 'diagnostics.log')).Count-ne3){throw 'diagnostics log did not preserve all injected failures'};Write-Output 'PASS test-diagnostics injected=3 projections=JSON+screen+report+log loss=0'}finally{Remove-Item $temp -Recurse -Force}
